def linsvm_sklearn(X, y, C):
    from sklearn.svm import LinearSVC

    svm = LinearSVC(C=C, loss="squared_hinge", tol=1e-5, max_iter=20_000).fit(X, y)  # one-vs-rest
    return np.vstack([svm.coef_.T, svm.intercept_])  # (D + 1, K)

